    /** All entries, sorted by legacy class name. */
    public List<OperacionRegistrada> todas() {
        return OPERACIONES;
    }

    /** Looks up by legacy FQN ({@code cl.bcs.APV.GrabarContratoSAAPV}) or by simple class name. */
    public Optional<OperacionRegistrada> buscar(String claseLegacy) {
        if (claseLegacy == null) {
            return Optional.empty();
        }
        String fqn = claseLegacy.startsWith(PREFIJO) ? claseLegacy : PREFIJO + claseLegacy;
        return OPERACIONES.stream().filter(o -> o.claseLegacy().equals(fqn)).findFirst();
    }
